export function selectDue(reminders,now){
 if(!Number.isSafeInteger(now)||now<0)throw new RangeError('clock');
 const result=[];for(const item of reminders)if(item.enabled&&item.dueAt!==null&&now>=item.dueAt)result.push(item);return result;
}

